add_cat_of_random_age :: proc(cats: ^[dynamic]Cat, name: string) {
	random_age := rand.int_max(12) + 2
	append(cats, Cat {
		name = name,
		age = random_age,
	})
}

count_total :: proc(score: ^[dynamic]Entity, size: string) {
	result_set := rand.int_max(13) + 2
	append(score, Entity {
		size = size,
		level = result_set,
	})
}

total_sum :: proc(size: ^[dynamic]Record, level: string) {
	count_total := rand.int_max(100) + 2
	append(size, Record {
		level = level,
		value = count_total,
	})
}

